import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError("The script file does not exist.")
    result = {"message": None}
    def run_script():
        try:
            process = subprocess.run(["python", script_path], timeout=timeout)
            result["message"] = "Script executed successfully."
        except subprocess.TimeoutExpired:
            result["message"] = "Terminating process due to timeout."
    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout)
    if thread.is_alive():
        result["message"] = "Terminating process due to timeout."
    return result["message"]

